/* English build of bot.js — generated by cli/i18n.php, do not edit */
/*
 * Customer service bot: Chat page (Refresh Automatic and Reply, in Admin panel ونظام Network owner)
 * and Page Settings in Admin panel (Test القنوات and Try the assistant بnumbers).
 */
(function (window, document) {
  'use strict';
  var SN = window.SN;
  if (!SN) { return; }

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) { n.className = cls; }
    if (text !== undefined && text !== null) { n.textContent = text; }
    return n;
  }
  function enterSends(textarea, form) {
    textarea.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
        e.preventDefault();
        if (form.requestSubmit) { form.requestSubmit(); } else { form.dispatchEvent(new Event('submit', { cancelable: true })); }
      }
    });
    textarea.addEventListener('input', function () {
      textarea.style.height = 'auto';
      textarea.style.height = Math.min(140, textarea.scrollHeight) + 'px';
    });
  }

  // ---------------------------------------------------------------------
  // Chat page
  // ---------------------------------------------------------------------
  var thread = document.querySelector('[data-bot-thread]');
  if (thread) {
    var log = thread.querySelector('[data-bot-log]');
    var last = parseInt(thread.getAttribute('data-last'), 10) || 0;
    var userLabel = thread.getAttribute('data-user-label') || 'Sender';
    var label = function (m) {
      if (m.role === 'user') { return userLabel; }
      if (m.role === 'bot') { return 'Auto assistant'; }
      if (m.role === 'staff') { return (m.sender ? m.sender + ' · ' : '') + (m.side === 'network' ? 'Network owner' : 'Platform team'); }
      return 'Note';
    };
    var toBottom = function () { log.scrollTop = log.scrollHeight; };
    toBottom();

    var add = function (m) {
      if (log.querySelector('[data-id="' + m.id + '"]')) { return; }
      var node;
      if (m.role === 'note') {
        node = el('div', 'bot-note');
        node.innerHTML = SN.icon('info');
        node.appendChild(el('span', '', m.body));
        node.appendChild(el('small', '', m.at));
      } else {
        node = el('div', 'chat-msg ' + (m.role === 'user' ? 'is-user' : 'is-assistant') + (m.role === 'staff' ? ' is-staff' : ''));
        node.appendChild(el('span', 'bot-msg-meta', label(m) + ' · ' + m.at + (m.tools ? ' · ' + m.tools : '')));
        node.appendChild(document.createTextNode(m.body));
      }
      node.setAttribute('data-id', m.id);
      log.appendChild(node);
      last = Math.max(last, m.id);
    };

    var modeBadge = thread.querySelector('[data-bot-mode]');
    var polling = false;
    var poll = function () {
      if (polling || document.hidden) { return; }
      polling = true;
      SN.api(thread.getAttribute('data-poll') + '?after=' + last)
        .then(function (r) {
          var near = log.scrollHeight - log.scrollTop - log.clientHeight < 80;
          (r.messages || []).forEach(add);
          if (r.messages && r.messages.length && near) { toBottom(); }
          var waiting = thread.querySelector('[data-bot-waiting]');
          if (waiting) { waiting.hidden = !(r.needs_human && r.status === 'open'); }
          if (modeBadge) {
            modeBadge.textContent = r.mode === 'human' ? 'With a person' : 'With the auto assistant';
            modeBadge.className = 'badge ' + (r.mode === 'human' ? 'badge-info' : 'badge-primary');
          }
        })
        .catch(function () {})
        .then(function () { polling = false; });
    };
    window.setInterval(poll, 5000);

    var form = thread.querySelector('[data-bot-reply]');
    if (form) {
      var input = form.querySelector('textarea');
      var btn = form.querySelector('button');
      enterSends(input, form);
      form.addEventListener('submit', function (e) {
        e.preventDefault();
        var body = input.value.trim();
        if (!body || btn.disabled) { return; }
        btn.disabled = true;
        btn.classList.add('is-loading');
        SN.api(thread.getAttribute('data-reply'), { method: 'POST', data: { body: body } })
          .then(function () {
            input.value = '';
            input.style.height = '';
            poll();
            window.setTimeout(toBottom, 400);
          })
          .catch(function () {})
          .then(function () { btn.disabled = false; btn.classList.remove('is-loading'); input.focus(); });
      });
    }
  }

  // ---------------------------------------------------------------------
  // Page Settings
  // ---------------------------------------------------------------------
  SN.on(document, 'click', '[data-bot-test]', function (e, b) {
    e.preventDefault();
    var fields = {};
    try { fields = JSON.parse(b.getAttribute('data-fields') || '{}'); } catch (err) { fields = {}; }
    var data = {};
    Object.keys(fields).forEach(function (k) {
      var f = document.querySelector(fields[k]);
      data[k] = f ? f.value.trim() : '';
    });
    b.classList.add('is-loading');
    SN.api(b.getAttribute('data-bot-test'), { method: 'POST', data: data })
      .then(function (r) { SN.toast('success', r.message); })
      .catch(function () {})
      .then(function () { b.classList.remove('is-loading'); });
  });

  var counter = document.querySelector('[data-count-for]');
  if (counter) {
    var area = document.getElementById(counter.getAttribute('data-count-for'));
    var max = parseInt(counter.getAttribute('data-max'), 10) || 0;
    var count = function () { counter.textContent = SN.fmtNum(area.value.length) + ' / ' + SN.fmtNum(max); };
    if (area) { area.addEventListener('input', count); count(); }
  }

  var tryBox = document.querySelector('[data-bot-try]');
  if (tryBox) {
    var tlog = tryBox.querySelector('[data-bot-try-log]');
    var tform = tryBox.querySelector('[data-bot-try-form]');
    var tinput = tform.querySelector('textarea');
    var tbtn = tform.querySelector('button');
    var tphone = tryBox.querySelector('[data-bot-try-phone]');
    if (tphone) {
      // Number New Starts New chat بهويته (and Server يمسح القديمة)
      tphone.addEventListener('change', function () { tlog.innerHTML = ''; });
    }
    var bubble = function (cls, text, meta) {
      var n = el('div', 'chat-msg ' + cls);
      if (meta) { n.appendChild(el('span', 'bot-msg-meta', meta)); }
      n.appendChild(document.createTextNode(text));
      tlog.appendChild(n);
      tlog.scrollTop = tlog.scrollHeight;
      return n;
    };
    enterSends(tinput, tform);
    tform.addEventListener('submit', function (e) {
      e.preventDefault();
      var text = tinput.value.trim();
      if (!text || tbtn.disabled) { return; }
      tinput.value = '';
      tinput.style.height = '';
      bubble('is-user', text);
      var typing = bubble('is-assistant is-typing', '');
      tbtn.disabled = true;
      SN.api(tryBox.getAttribute('data-url'), { method: 'POST', data: { text: text, phone: tphone ? tphone.value.trim() : '' } })
        .then(function (r) {
          typing.remove();
          var meta = [];
          if (r.as) { meta.push(r.as); }
          if (r.tools) { meta.push(r.tools); }
          if (r.handoff) { meta.push(r.handoff); }
          bubble('is-assistant', r.reply, meta.join(' · '));
        })
        .catch(function (err) {
          typing.remove();
          bubble('is-assistant is-error', err.message);
        })
        .then(function () { tbtn.disabled = false; tinput.focus(); });
    });
    var reset = tryBox.querySelector('[data-bot-try-reset]');
    if (reset) {
      reset.addEventListener('click', function () {
        SN.api(tryBox.getAttribute('data-url'), { method: 'POST', data: { reset: 1 } })
          .then(function () { tlog.innerHTML = ''; })
          .catch(function () {});
      });
    }
  }
})(window, document);
